import React from 'react';

export default function Blobs({ variant = 'default' }) {
  const configs = {
    default: [
      { w:420, h:420, top:'-10%', left:'-10%',  bg:'rgba(100,80,180,0.18)', anim:'float 9s ease-in-out infinite' },
      { w:320, h:320, top:'40%',  right:'-8%',  bg:'rgba(60,60,120,0.14)',  anim:'floatAlt 12s ease-in-out infinite' },
      { w:260, h:260, bottom:'5%',left:'30%',   bg:'rgba(80,60,160,0.12)',  anim:'float 15s ease-in-out infinite 2s' },
    ],
    blue: [
      { w:500, h:500, top:'-15%', left:'-15%', bg:'rgba(40,60,140,0.2)',   anim:'float 11s ease-in-out infinite' },
      { w:350, h:350, bottom:'0', right:'-10%', bg:'rgba(60,80,180,0.15)', anim:'floatAlt 9s ease-in-out infinite' },
    ],
    warm: [
      { w:400, h:400, top:'10%', right:'-10%', bg:'rgba(120,80,100,0.18)', anim:'float 10s ease-in-out infinite' },
      { w:300, h:300, bottom:'10%', left:'-5%', bg:'rgba(80,60,120,0.14)', anim:'floatAlt 13s ease-in-out infinite' },
    ],
  };

  const blobs = configs[variant] || configs.default;

  return (
    <div style={{ position:'fixed', inset:0, zIndex:0, pointerEvents:'none', overflow:'hidden' }}>
      {blobs.map((b, i) => (
        <div key={i} style={{
          position:'absolute',
          width:b.w, height:b.h,
          top:b.top, left:b.left, right:b.right, bottom:b.bottom,
          background:b.bg,
          borderRadius:'50%',
          filter:'blur(80px)',
          animation:b.anim,
        }} />
      ))}
      {/* Noise texture overlay */}
      <div style={{
        position:'absolute', inset:0,
        backgroundImage:`url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='1'/%3E%3C/svg%3E")`,
        opacity:0.025,
      }} />
    </div>
  );
}
